"""Backend copy catalog fragments kept outside orchestration code.

Model policy is intentionally stored once and reused for every response style:
the separate language instruction controls the model's output language and cat
tone.  User-visible entries below provide real product-language variants.
"""

from __future__ import annotations

from typing import Final


LocalizedEntry = tuple[str, str, str, str, str]


def _model_copy(value: str) -> LocalizedEntry:
    """Return one canonical policy for all model input languages."""
    return (value, value, value, value, value)


def _user_copy(zh_cn: str, en: str, zh_tw: str = "") -> LocalizedEntry:
    """Build complete product variants for concise runtime fallback copy."""
    return (zh_cn, zh_tw or zh_cn, en, zh_cn, zh_cn)


